test("valid matches node-semver strict validation", () => {
  for (const { version, expected } of VALID_CASES) {
    assert.equal(valid(version), expected, `valid(${version})`);
  }
});

test("compare follows SemVer precedence", () => {
  for (const { a, b, expected } of COMPARE_CASES) {
    assert.equal(compare(a, b), expected, `compare(${a}, ${b})`);
    assert.equal(gt(a, b), expected > 0, `gt(${a}, ${b})`);
  }
});

test("satisfies matches node-semver for the supported range forms", () => {
  for (const { version, range, includePrerelease, expected } of SATISFIES_CASES) {
    assert.equal(satisfies(version, range, { includePrerelease }), expected,
      `satisfies(${version}, ${range}, includePrerelease=${includePrerelease})`);
  }
});

test("satisfies never throws on an invalid range", () => {
  for (const range of [">=foo", "not-a-version", "^^1.2.3", ">=", "1.x.3"]) {
    assert.equal(satisfies("1.2.3", range), false, range);
  }
});
